#!/bin/bash
# Read-only: count open (Bidding) bids at candidate PlanetBids agencies with the production browser reader.
IDS="14660 39483 43976 11434 42510 40532 53681 66785 39500 39485 19768 63777 16339 50139 91387 65344 48006 15300 39495 21372 42035 69231 42217 39493 61954 22761 41481 36746 48551 24103 56603 20137 25002 24662 71685 15340 39475 14773 29414 40135 39497 17920 20136 51469 71895 23758 67229 74789 43764 59999 52215 20507 44169 39494 15598 21910 14663 14769 73214"
for id in $IDS; do
  PLANETBIDS_CID=$id PLANETBIDS_OUT=/tmp/pb-$id.json timeout 170 node "$RUNNER_TEMP/pb/planetbids-bids-fetch.mjs" 2>&1 | tail -1 | sed "s/^/CID $id: /"
  sleep 3
done
